-- =============================================================================
-- StudyOS seed data — representative CBSE Class 12 Science catalogue.
--
-- Safe to re-run: natural keys use `on conflict ... do nothing` and generated
-- rows are guarded with `where not exists`. Chapter slugs are generated by the
-- same rules as the app's slugify() (src/utils/format.ts) and match the bundled
-- sample dataset in src/data/subjects.ts exactly, so deep links keep working.
--
-- Contents:
--   boards (CBSE + friends), classes 9-10-11-12 & other, streams
--   CBSE Class 12 Science subjects (Physics, Chemistry, Mathematics, English,
--   Computer Science — English & Mathematics have a null stream so they show up
--   in Science, Commerce and Humanities alike, exactly like the demo data)
--   ~8-13 chapters per subject with topics/difficulty/estimates
--   a handful of resources per chapter (notes / video / reference / formula /
--   important questions)
--   54 PYQ questions across 2019-2024 with marks, sections, difficulty,
--   concepts and repeat groups (shared group_key = repeated question)
--   exam templates cloned into student calendars at onboarding
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Boards / classes / streams
-- ---------------------------------------------------------------------------
insert into public.boards (slug, name, short_name, description, display_order)
values
  ('cbse', 'CBSE', 'CBSE', 'Central Board of Secondary Education — NCERT aligned.', 1),
  ('icse', 'ICSE', 'ICSE', 'Council for the Indian School Certificate Examinations.', 2),
  ('isc', 'ISC', 'ISC', 'Indian School Certificate — Class 11 & 12 focus.', 3),
  ('state-boards', 'State Boards', 'STATE', 'Maharashtra, Tamil Nadu, UP, WB, Karnataka and 15 more.', 4),
  ('other', 'Other', 'OTHER', 'IB, IGCSE, NIOS and open schooling curricula.', 5)
on conflict (slug) do nothing;

insert into public.classes (slug, name, description, display_order, senior)
values
  ('class-9', 'Class 9', 'Build the fundamentals', 1, false),
  ('class-10', 'Class 10', 'First board examination', 2, false),
  ('class-11', 'Class 11', 'Stream foundations', 3, true),
  ('class-12', 'Class 12', 'Board year — everything on the line', 4, true),
  ('other', 'Other', 'Diploma, entrance or custom syllabus', 5, true)
on conflict (slug) do nothing;

insert into public.streams (slug, name, description, display_order)
values
  ('science', 'Science', 'Physics, Chemistry, Mathematics / Biology', 1),
  ('commerce', 'Commerce', 'Accountancy, Business Studies, Economics', 2),
  ('humanities', 'Humanities', 'History, Political Science, Geography, Psychology', 3)
on conflict (slug) do nothing;

-- ---------------------------------------------------------------------------
-- Subjects — CBSE Class 12 Science
-- stream_id is null for shared subjects (English + Mathematics), which the app
-- treats as "offered by every stream" (see getStreams() in academic.service).
-- ---------------------------------------------------------------------------
insert into public.subjects (slug, class_id, board_id, stream_id, name, code, description, display_order)
select
  v.slug,
  cls.id,
  brd.id,
  case when v.shared then null else sci.id end,
  v.name,
  v.code,
  v.description,
  v.display_order
from (values
  ('physics',         'Physics',         '042', 'Mechanics, electricity, optics and modern physics — NCERT aligned with PYQ drill-downs.', 1, false),
  ('chemistry',       'Chemistry',       '043', 'Physical, organic and inorganic chemistry with reaction maps and equation drills.', 2, false),
  ('mathematics',     'Mathematics',     '041', 'Calculus, algebra, vectors and probability with step-by-step solved PYQs.', 3, true),
  ('english',         'English',         '301', 'Flamingo and Vistas core reader with extract practice and long-answer frameworks.', 4, true),
  ('computer-science','Computer Science','083', 'Python, data structures, SQL and networks — theory paired with coding practice.', 5, false)
) as v(slug, name, code, description, display_order, shared)
cross join (select id from public.classes where slug = 'class-12') cls
cross join (select id from public.boards where slug = 'cbse') brd
left join (select id from public.streams where slug = 'science') sci on true
on conflict (class_id, slug) do nothing;

-- ---------------------------------------------------------------------------
-- Chapters — slugs match src/data/subjects.ts exactly
-- ---------------------------------------------------------------------------

-- Physics (12 chapters)
