from (values
  (1,  'electrostatics', 'Electrostatics', 'Electric charges, fields, potential and the physics of capacitors.', 'Moderate', 240,
    array['Electric charges and fields', 'Electrostatic potential', 'Capacitors and dielectrics', 'Conductors']),
  (2,  'current-electricity', 'Current Electricity', 'Ohm’s law, drift velocity, and the bridge experiments that define the chapter.', 'Moderate', 210,
    array['Ohm’s law and resistance', 'Drift velocity', 'Kirchhoff’s laws', 'Wheatstone bridge', 'Meter bridge and potentiometer']),
  (3,  'moving-charges-and-magnetism', 'Moving Charges and Magnetism', 'Magnetic fields produced by moving charge and current-carrying conductors.', 'Hard', 220,
    array['Biot–Savart law', 'Ampère’s law', 'Cyclotron', 'Moving coil galvanometer', 'Torque on a dipole']),
