    array['Displacement current', 'Characteristics of EM waves', 'EM spectrum']),
  (7,  'ray-optics', 'Ray Optics', 'Reflection, refraction, lenses and optical instruments.', 'Moderate', 190,
    array['Reflection at spherical mirrors', 'Refraction and total internal reflection', 'Refraction by spherical lenses', 'Optical instruments']),
  (8,  'wave-optics', 'Wave Optics', 'Huygens, interference, diffraction and polarisation.', 'Hard', 170,
    array['Huygens’ principle', 'YDSE and interference', 'Diffraction', 'Polarisation']),
  (9,  'dual-nature-of-radiation-and-matter', 'Dual Nature of Radiation and Matter', 'Photoelectric effect, photons and de Broglie’s hypothesis.', 'Moderate', 150,
    array['Emission of electrons', 'Photoelectric effect', 'Wave nature of matter']),
  (10, 'atoms', 'Atoms', 'Rutherford, Bohr and the hydrogen spectrum.', 'Moderate', 130,
    array['Atomic models', 'Bohr postulates', 'Hydrogen spectrum', 'Energy levels']),
  (11, 'nuclei', 'Nuclei', 'Binding energy, radioactivity, fission and fusion.', 'Hard', 140,
    array['Nuclear size and density', 'Binding energy', 'Radioactive decay', 'Fission and fusion']),
  (12, 'semiconductor-electronics', 'Semiconductor Electronics', 'Junction diodes, Zener regulators and logic gates.', 'Easy', 150,
    array['Intrinsic and extrinsic semiconductors', 'p–n junction', 'Zener diode', 'Logic gates', 'Photodiodes and LEDs'])
) as v(chapter_number, slug, name, description, difficulty, estimated_minutes, topics)
join public.subjects sub on sub.slug = 'physics'
join public.classes cls on cls.id = sub.class_id and cls.slug = 'class-12'
on conflict (subject_id, slug) do nothing;

