-- ---------------------------------------------------------------------------
-- Chapter resources (generated: notes / video / reference / formula /
-- important questions per chapter). file_path stays null until a real file is
-- uploaded to the `resources` storage bucket; the app then uses signed URLs.
-- ---------------------------------------------------------------------------
insert into public.resources (
  chapter_id, title, description, resource_type,
  page_count, question_count, file_size_bytes, source_name, is_published
)
select
  ch.id,
  ch.name || ' — ' || t.label,
  t.description,
  t.resource_type,
  t.page_count,
  t.question_count,
  t.file_size_bytes,
  t.source_name,
  true
from public.chapters ch
join public.subjects sub on sub.id = ch.subject_id
join public.classes cls on cls.id = sub.class_id and cls.slug = 'class-12'
cross join (values
  ('notes',                'NCERT Notes',         'Concept notes aligned with the NCERT textbook.',                       14, null::integer, 3200000::bigint,  'StudyOS'),
  ('video',                'Video Lecture',       'Chapter-wise video lecture with worked examples.',                     null::integer, null::integer, 28000000::bigint, 'StudyOS'),
  ('reference_material',   'Reference Material',  'Extra reference material, solved examples and labelled diagrams.',     10, null::integer, 1800000::bigint,  'NCERT'),
  ('formula_sheet',        'Formula Sheet',       'Every equation, constant and unit you need in the exam hall.',           6, null::integer, 700000::bigint,   'StudyOS'),
  ('important_questions',  'Important Questions', 'High-probability questions ranked by repetition over the last decade.', null::integer, 40, 900000::bigint, 'StudyOS')
) as t(resource_type, label, description, page_count, question_count, file_size_bytes, source_name)
where not exists (
  select 1
  from public.resources r
  where r.chapter_id = ch.id
    and r.resource_type = t.resource_type
    and r.title = ch.name || ' — ' || t.label
);

-- ---------------------------------------------------------------------------
-- PYQ archive — CBSE board papers, 2019-2024.
-- Questions repeating across years share a group_key (the intelligence
-- dashboard computes the repeat rate from it); exam_type 'board' + paper_set
-- 'Set 1' group rows into one "paper" per subject/year in the app.
-- ---------------------------------------------------------------------------
insert into public.pyq_questions (
  chapter_id, subject_id, board_id, class_id, year, exam_type, question_text,
  question_type, paper_set, marks, difficulty, concepts, group_key, is_important, source
)
select
  ch.id, sub.id, b.id, cls.id, v.year, v.exam_type, v.question_text,
  v.question_type, v.paper_set, v.marks, v.difficulty, v.concepts, v.group_key, v.is_important,
  'CBSE ' || v.year || ' board exam'
from (values
  -- Physics
  ('physics', 'electromagnetic-induction', 2024, 'board', 'Derive an expression for the instantaneous emf induced in a rectangular coil rotating in a uniform magnetic field.', 'long_answer', 'Set 1', 5, 'hard', array['Faraday’s law', 'Motional emf'], 'phy-faraday-lenz', true),
  ('physics', 'electromagnetic-induction', 2021, 'board', 'State Lenz’s law. Show how it follows from the law of conservation of energy.', 'short_answer', 'Set 1', 3, 'moderate', array['Faraday’s law', 'Lenz’s law'], 'phy-faraday-lenz', false),
  ('physics', 'current-electricity', 2023, 'board', 'State Kirchhoff''s laws of electrical circuits. Derive the condition for a balanced Wheatstone bridge.', 'short_answer', 'Set 1', 3, 'moderate', array['Kirchhoff''s Laws', 'Wheatstone Bridge'], 'phy-kirchhoff', true),
  ('physics', 'current-electricity', 2019, 'board', 'Explain how the balance condition of a Wheatstone bridge is used to determine an unknown resistance with a metre bridge.', 'short_answer', 'Set 1', 3, 'moderate', array['Wheatstone Bridge', 'Meter bridge and potentiometer'], 'phy-kirchhoff', false),
  ('physics', 'current-electricity', 2022, 'board', 'A uniform wire of resistance 16 Ω is stretched to twice its original length. Calculate its new resistance.', 'numerical', 'Set 1', 1, 'easy', array['Resistance and resistivity'], null, false),
  ('physics', 'alternating-current', 2023, 'board', 'Describe the working of an LCR series circuit with a labelled phasor diagram. Define resonant frequency.', 'long_answer', 'Set 1', 5, 'hard', array['LCR resonance', 'Power factor'], 'phy-lcr', true),
  ('physics', 'alternating-current', 2019, 'board', 'Explain the phenomenon of resonance in an LCR circuit and obtain an expression for the resonant frequency.', 'short_answer', 'Set 1', 3, 'moderate', array['LCR resonance'], 'phy-lcr', false),
  ('physics', 'atoms', 2024, 'board', 'Using Bohr’s model, derive the expression for the radius of the nth orbit of the hydrogen atom and state the quantisation condition.', 'short_answer', 'Set 1', 3, 'moderate', array['Bohr model', 'Hydrogen spectrum'], 'phy-bohr', true),
  ('physics', 'atoms', 2020, 'board', 'The energy of an electron in the second orbit of a hydrogen atom is closest to:', 'MCQ', 'Set 1', 1, 'easy', array['Bohr model', 'Energy levels'], 'phy-bohr', false),
  ('physics', 'electrostatics', 2021, 'board', 'Define electric potential due to a system of charges. Derive an expression for the potential at a point due to a point charge.', 'short_answer', 'Set 1', 3, 'moderate', array['Electric potential'], null, false),
  ('physics', 'ray-optics', 2022, 'board', 'A convex lens of focal length 20 cm forms a real image twice the size of the object. Find the object distance.', 'short_answer', 'Set 1', 3, 'moderate', array['Lens formula', 'Magnification'], null, false),
  ('physics', 'dual-nature-of-radiation-and-matter', 2024, 'board', 'Explain how the photoelectric effect establishes the particle nature of light. Draw the variation of stopping potential with frequency.', 'case_study', 'Set 1', 5, 'hard', array['Photoelectric effect', 'Work function'], 'phy-photoelectric', true),
  ('physics', 'wave-optics', 2019, 'board', 'State the conditions for constructive and destructive interference in Young''s double slit experiment.', 'assertion_reason', 'Set 1', 2, 'moderate', array['YDSE and interference'], 'phy-ydse', false),
  ('physics', 'electromagnetic-waves', 2022, 'board', 'Arrange the following in increasing order of frequency: radio waves, gamma rays, visible light and X-rays.', 'MCQ', 'Set 1', 1, 'easy', array['EM spectrum'], null, false)
) as v(subject_slug, chapter_slug, year, exam_type, question_text, question_type, paper_set, marks, difficulty, concepts, group_key, is_important)
join public.subjects sub on sub.slug = v.subject_slug
join public.classes cls on cls.id = sub.class_id and cls.slug = 'class-12'
join public.chapters ch on ch.subject_id = sub.id and ch.slug = v.chapter_slug
cross join (select id from public.boards where slug = 'cbse') b
where not exists (
  select 1 from public.pyq_questions p where p.question_text = v.question_text
);

insert into public.pyq_questions (
  chapter_id, subject_id, board_id, class_id, year, exam_type, question_text,
  question_type, paper_set, marks, difficulty, concepts, group_key, is_important, source
)
select
  ch.id, sub.id, b.id, cls.id, v.year, v.exam_type, v.question_text,
  v.question_type, v.paper_set, v.marks, v.difficulty, v.concepts, v.group_key, v.is_important,
  'CBSE ' || v.year || ' board exam'
from (values
  -- Chemistry
  ('chemistry', 'electrochemistry', 2024, 'board', 'State the Nernst equation. Calculate the emf of the cell Zn | Zn²⁺ (0.1 M) ‖ Cu²⁺ (0.01 M) | Cu at 298 K.', 'long_answer', 'Set 1', 5, 'hard', array['Nernst Equation', 'Electrochemical cells'], 'chem-nernst', true),
  ('chemistry', 'electrochemistry', 2022, 'board', 'The conductivity of 0.001 M acetic acid is 4.95 × 10⁻⁵ S cm⁻¹. Calculate its molar conductivity and comment on its degree of dissociation.', 'numerical', 'Set 1', 3, 'moderate', array['Conductance and conductivity'], null, false),
  ('chemistry', 'alcohols-phenols-and-ethers', 2023, 'board', 'How will you convert phenol to aspirin? Write the reactions involved.', 'short_answer', 'Set 1', 3, 'moderate', array['Properties of alcohols and phenols', 'Williamson synthesis'], 'chem-phenol', true),
  ('chemistry', 'alcohols-phenols-and-ethers', 2020, 'board', 'Explain the Reimer–Tiemann reaction with a suitable example.', 'short_answer', 'Set 1', 3, 'moderate', array['Reimer–Tiemann and Kolbe reactions'], 'chem-phenol', false),
  ('chemistry', 'solutions', 2021, 'board', 'Which of the following aqueous solutions will have the highest boiling point?', 'MCQ', 'Set 1', 1, 'easy', array['Colligative properties'], null, false),
  ('chemistry', 'chemical-kinetics', 2024, 'board', 'For a first-order reaction the half-life is 20 minutes. Calculate the rate constant for the reaction.', 'numerical', 'Set 1', 2, 'moderate', array['Half-life', 'Rate law and order'], 'chem-kinetics', true),
  ('chemistry', 'chemical-kinetics', 2019, 'board', 'Derive the Arrhenius equation and explain the effect of temperature on the rate of a reaction.', 'short_answer', 'Set 1', 3, 'moderate', array['Arrhenius equation'], 'chem-kinetics', false),
  ('chemistry', 'coordination-compounds', 2022, 'board', 'Explain crystal field theory for octahedral complexes and calculate the CFSE for a d⁶ ion in a weak field ligand environment.', 'long_answer', 'Set 1', 5, 'hard', array['VBT and CFT', 'Isomerism'], null, true),
  ('chemistry', 'aldehydes-ketones-and-carboxylic-acids', 2023, 'board', 'Distinguish between propanal and propanone by a chemical test and write the underlying reaction.', 'short_answer', 'Set 1', 3, 'hard', array['Aldol and Cannizzaro reactions'], null, false),
  ('chemistry', 'haloalkanes-and-haloarenes', 2021, 'board', 'SN1 reactions proceed with racemisation while SN2 reactions give inversion of configuration.', 'assertion_reason', 'Set 1', 2, 'easy', array['Nucleophilic substitution', 'Elimination reactions'], null, false),
  ('chemistry', 'biomolecules', 2024, 'board', 'Describe the secondary structure of proteins with two examples.', 'short_answer', 'Set 1', 2, 'moderate', array['Proteins and amino acids'], null, false),
  ('chemistry', 'amines', 2019, 'board', 'Arrange the following in increasing order of basic strength in aqueous solution: methylamine, aniline, dimethylamine.', 'MCQ', 'Set 1', 1, 'easy', array['Physical and chemical properties'], null, false)
) as v(subject_slug, chapter_slug, year, exam_type, question_text, question_type, paper_set, marks, difficulty, concepts, group_key, is_important)
join public.subjects sub on sub.slug = v.subject_slug
join public.classes cls on cls.id = sub.class_id and cls.slug = 'class-12'
join public.chapters ch on ch.subject_id = sub.id and ch.slug = v.chapter_slug
cross join (select id from public.boards where slug = 'cbse') b
where not exists (
  select 1 from public.pyq_questions p where p.question_text = v.question_text
);

insert into public.pyq_questions (
  chapter_id, subject_id, board_id, class_id, year, exam_type, question_text,
  question_type, paper_set, marks, difficulty, concepts, group_key, is_important, source
)
select
  ch.id, sub.id, b.id, cls.id, v.year, v.exam_type, v.question_text,
  v.question_type, v.paper_set, v.marks, v.difficulty, v.concepts, v.group_key, v.is_important,
  'CBSE ' || v.year || ' board exam'
from (values
  -- Mathematics
  ('mathematics', 'integrals', 2024, 'board', 'Evaluate ∫ x·e^x dx using integration by parts. Hence evaluate the definite integral from 0 to 1 of x·e^x dx.', 'long_answer', 'Set 1', 5, 'hard', array['By parts', 'Definite integrals'], 'math-integrals', true),
  ('mathematics', 'integrals', 2020, 'board', 'Prove that the integral of f(x) from 0 to a equals the integral of f(a − x) from 0 to a, and hence evaluate ∫ sin x/(sin x + cos x) dx from 0 to π/2.', 'short_answer', 'Set 1', 3, 'hard', array['Definite integrals', 'Fundamental theorem'], 'math-integrals', false),
  ('mathematics', 'application-of-derivatives', 2023, 'board', 'Find the intervals in which the function f(x) = x³ − 3x² + 4 is strictly increasing.', 'short_answer', 'Set 1', 3, 'hard', array['Increasing and decreasing functions', 'Maxima and minima'], 'math-monotonicity', true),
  ('mathematics', 'application-of-derivatives', 2019, 'board', 'Find the equation of the tangent to the curve y = x² at the point (1, 1).', 'short_answer', 'Set 1', 2, 'moderate', array['Tangents and normals'], null, false),
  ('mathematics', 'matrices', 2022, 'board', 'If A is a square matrix of order 3 and |A| = 5, find the value of |2A|.', 'MCQ', 'Set 1', 1, 'easy', array['Matrix arithmetic', 'Properties of determinants'], null, false),
  ('mathematics', 'differential-equations', 2024, 'board', 'Solve the differential equation dy/dx + y·cot x = 2 cos x.', 'short_answer', 'Set 1', 3, 'hard', array['Linear differential equations'], null, true),
  ('mathematics', 'probability', 2021, 'board', 'A bag contains 5 red and 3 blue balls. Two balls are drawn at random. Find the probability that both are red.', 'short_answer', 'Set 1', 2, 'moderate', array['Total probability and Bayes’ theorem'], 'math-bayes', false),
  ('mathematics', 'probability', 2019, 'board', 'Using Bayes’ theorem, find the probability that a randomly chosen defective item was produced by machine A.', 'numerical', 'Set 1', 3, 'hard', array['Random variables', 'Total probability and Bayes’ theorem'], 'math-bayes', true),
  ('mathematics', 'vector-algebra', 2023, 'board', 'Show that (a × b)² = |a|²|b|² − (a · b)² for any two vectors a and b.', 'short_answer', 'Set 1', 2, 'moderate', array['Cross product', 'Dot product'], null, false),
  ('mathematics', 'three-dimensional-geometry', 2022, 'board', 'Find the shortest distance between the lines (x − 1)/2 = (y − 2)/3 = (z − 3)/4 and (x − 2)/3 = (y − 4)/4 = (z − 5)/5.', 'short_answer', 'Set 1', 3, 'moderate', array['Shortest distance', 'Equation of lines and planes'], null, false),
  ('mathematics', 'linear-programming', 2020, 'board', 'Solve the following linear programming problem graphically: maximise Z = 3x + 4y subject to the given constraints.', 'long_answer', 'Set 1', 5, 'moderate', array['Feasible region', 'Optimal solution'], null, false),
  ('mathematics', 'relations-and-functions', 2021, 'board', 'Check whether the relation R = {(a, b) : |a − b| = 1} on the set of integers is reflexive, symmetric and transitive.', 'short_answer', 'Set 1', 2, 'moderate', array['Types of relations'], null, false)
) as v(subject_slug, chapter_slug, year, exam_type, question_text, question_type, paper_set, marks, difficulty, concepts, group_key, is_important)
join public.subjects sub on sub.slug = v.subject_slug
join public.classes cls on cls.id = sub.class_id and cls.slug = 'class-12'
join public.chapters ch on ch.subject_id = sub.id and ch.slug = v.chapter_slug
cross join (select id from public.boards where slug = 'cbse') b
where not exists (
  select 1 from public.pyq_questions p where p.question_text = v.question_text
);

