  ('english', 'the-tiger-king', 2020, 'board', 'How does Kalki use satire to expose the vanity of the Maharaja of Pratibandapuram?', 'short_answer', 'Set 1', 3, 'easy', array['Satire', 'Irony'], null, false),
  ('english', 'poets-and-pancakes', 2024, 'board', 'What does Asokamitran say about the hierarchy and the cabin system at Gemini Studios?', 'MCQ', 'Set 1', 1, 'easy', array['Humour and satire'], null, false),
