insert into public.pyq_questions (
  chapter_id, subject_id, board_id, class_id, year, exam_type, question_text,
  question_type, paper_set, marks, difficulty, concepts, group_key, is_important, source
)
select
  ch.id, sub.id, b.id, cls.id, v.year, v.exam_type, v.question_text,
  v.question_type, v.paper_set, v.marks, v.difficulty, v.concepts, v.group_key, v.is_important,
