from (values
  -- Computer Science
  ('computer-science', 'computer-networks', 2024, 'board', 'Explain the functions of each layer of the OSI reference model with a suitable example for every layer.', 'short_answer', 'Set 1', 3, 'hard', array['OSI and TCP/IP models'], 'cs-osi', true),
  ('computer-science', 'computer-networks', 2021, 'board', 'Differentiate between guided and unguided transmission media with two examples of each.', 'short_answer', 'Set 1', 3, 'moderate', array['Transmission media'], 'cs-osi', false),
  ('computer-science', 'database-concepts-and-sql', 2023, 'board', 'What is normalisation? Convert the given relation into BCNF.', 'short_answer', 'Set 1', 3, 'moderate', array['Normalisation', 'Relational model and keys'], 'cs-sql', true),
  ('computer-science', 'database-concepts-and-sql', 2020, 'board', 'A primary key is:', 'MCQ', 'Set 1', 1, 'easy', array['Relational model and keys'], 'cs-sql', false),
  ('computer-science', 'python-revision-tour-and-functions', 2022, 'board', 'Write a Python function to check whether a given string is a palindrome, using recursion.', 'short_answer', 'Set 1', 3, 'easy', array['Recursion', 'Functions and scope'], null, false),
  ('computer-science', 'file-handling', 2024, 'board', 'Which file mode is used to open a file for appending data at its end?', 'MCQ', 'Set 1', 1, 'easy', array['File modes'], null, false),
  ('computer-science', 'sorting-and-searching', 2019, 'board', 'Write an algorithm for binary search. What is its time complexity in the worst case?', 'short_answer', 'Set 1', 3, 'moderate', array['Linear and binary search', 'Complexity analysis'], null, false),
  ('computer-science', 'data-structures-stack-and-queue', 2023, 'board', 'Convert the infix expression A + B × C − D into its postfix form using a stack.', 'short_answer', 'Set 1', 3, 'moderate', array['Infix to postfix', 'Stack operations'], null, false)
) as v(subject_slug, chapter_slug, year, exam_type, question_text, question_type, paper_set, marks, difficulty, concepts, group_key, is_important)
join public.subjects sub on sub.slug = v.subject_slug
join public.classes cls on cls.id = sub.class_id and cls.slug = 'class-12'
join public.chapters ch on ch.subject_id = sub.id and ch.slug = v.chapter_slug
cross join (select id from public.boards where slug = 'cbse') b
where not exists (
  select 1 from public.pyq_questions p where p.question_text = v.question_text
);

-- ---------------------------------------------------------------------------
-- Exam templates — copied into a student's calendar when onboarding finishes
-- (exam.service.assignExamsForProfile() or the clone_exam_templates() RPC).
-- ---------------------------------------------------------------------------
insert into public.exam_templates (board_id, class_id, subject_id, title, exam_date, total_marks, notes, color)
select
  b.id,
  cls.id,
  sub.id,
  v.title,
  v.exam_date::date,
  v.total_marks,
  v.notes,
  v.color
from (values
  ('Unit Test III — Physics & Chemistry', '2026-10-21', 40, 'Chapter-wise unit tests covering the mid-term syllabus.', 'warning', 'physics'),
  ('Pre-Board Examination',                '2026-12-08', 100, 'Full syllabus pre-board — the dress rehearsal.', 'brand', null),
  ('CBSE Class 12 — English Core',         '2027-02-17', 80, 'English Core board paper.', 'accent', 'english'),
  ('CBSE Class 12 — Physics',              '2027-02-22', 70, 'Physics board paper.', 'danger', 'physics'),
  ('CBSE Class 12 — Chemistry',            '2027-03-01', 70, 'Chemistry board paper.', 'accent', 'chemistry'),
  ('CBSE Class 12 — Mathematics',          '2027-03-09', 80, 'Mathematics board paper.', 'brand', 'mathematics')
) as v(title, exam_date, total_marks, notes, color, subject_slug)
cross join (select id from public.boards where slug = 'cbse') b
cross join (select id from public.classes where slug = 'class-12') cls
left join public.subjects sub on sub.slug = v.subject_slug and sub.class_id = cls.id
where not exists (
  select 1 from public.exam_templates t
  where t.board_id = b.id and t.class_id = cls.id and t.title = v.title
);
